export type Item = { sku: string; price: number; qty: number };
export type Coupon = { kind: "percent"; value: number; maxOff?: number } | { kind: "fixed"; value: number };

// Tax rate in basis points (1bp = 0.01%) so cent math stays integer.
const TAX_BPS: Record<string, number> = { CA: 725, NY: 400, OR: 0 };

const cents = (dollars: number) => Math.round(dollars * 100);

/** Subtotal in dollars. */
export function subtotal(items: Item[]): number {
  return items.reduce((s, i) => s + cents(i.price) * i.qty, 0) / 100;
}

/** Bulk pricing: 10% off a line when qty >= 10. */
export function lineTotal(i: Item): number {
  const gross = cents(i.price) * i.qty;
  return (i.qty >= 10 ? Math.round(gross * 0.9) : gross) / 100;
}

export function applyCoupon(amount: number, c?: Coupon): number {
  const a = cents(amount);
  if (!c) return a / 100;
  if (c.kind === "fixed") return Math.max(0, a - cents(c.value)) / 100;
  let off = (a * c.value) / 100;
  if (c.maxOff !== undefined) off = Math.min(off, cents(c.maxOff));
  return (a - Math.round(off)) / 100;
}

export function tax(amount: number, region: string): number {
  const bps = TAX_BPS[region];
  if (bps === undefined) throw new Error(`unknown region: ${region}`);
  return Math.round((cents(amount) * bps) / 10000) / 100;
}

/** Final total, rounded to cents. */
export function total(items: Item[], region: string, c?: Coupon): number {
  const base = items.reduce((s, i) => s + cents(lineTotal(i)), 0);
  const discounted = cents(applyCoupon(base / 100, c));
  return (discounted + cents(tax(discounted / 100, region))) / 100;
}
